class CalibrationMethod(BaseEstimator):
    """Adaptive Multi-Model Calibration (AMMC).

    Novel post-hoc calibration that fits multiple models of increasing
    complexity and selects the best via BIC, preventing overfitting on
    small calibration sets.

    Key innovation: principled model selection across complexity levels.
    - Well-calibrated models (GBM) → identity or temperature (few params)
    - Miscalibrated models (RF, MLP) → per-class temp+bias (more params)

    For binary:
      Model 0: Identity (0 params)
      Model 1: Temperature scaling (1 param)
      Model 2: Linear logit transform / Platt (2 params)

    For multiclass:
      Model 0: Identity (0 params)
      Model 1: Single temperature (1 param)
      Model 2: Per-class temperature (C params)
      Model 3: Per-class temperature + bias (2C params)
    """

    def __init__(self):
        self.is_binary = None
        self.model_type_ = None
        self.params_ = {}

    @staticmethod
    def _nll_from_logits(logits_2d, labels):
        """Compute mean NLL from 2D logits (numerically stable)."""
        eps = 1e-15
        n = len(labels)
        s = logits_2d - logits_2d.max(axis=1, keepdims=True)
        e = np.exp(s)
        lp = s - np.log(e.sum(axis=1, keepdims=True) + eps)
        return -lp[np.arange(n), labels.astype(int)].mean()

    def fit(self, probs, labels):
        eps = 1e-15
        n = len(labels)
        log_n = np.log(max(n, 2))

        if probs.ndim == 1:
            self.is_binary = True
            p = np.clip(probs, eps, 1 - eps)
            logits_2d = np.column_stack([np.log(1 - p), np.log(p)])
            logit_p = np.log(p / (1 - p))

            # --- Model 0: Identity ---
            nll0 = self._nll_from_logits(logits_2d, labels)
            bic0 = nll0 * n

            # --- Model 1: Single temperature (1 param) ---
            def temp_obj(T_arr):
                T = max(T_arr[0], 0.01)
                return self._nll_from_logits(logits_2d / T, labels)

            best1 = None
            for t0 in [0.3, 0.5, 1.0, 1.5, 2.0, 3.0, 5.0, 8.0]:
                r = optimize.minimize(temp_obj, x0=[t0],
                                      bounds=[(0.01, 50.0)], method="L-BFGS-B")
                if best1 is None or r.fun < best1.fun:
                    best1 = r
            bic1 = best1.fun * n + 1 * log_n

            # --- Model 2: Linear logit transform (2 params) ---
            def linear_obj(params):
                a, b = params
                lp = a * logit_p + b
                lp = np.clip(lp, -30, 30)
                pr = 1.0 / (1.0 + np.exp(-lp))
                pr = np.clip(pr, eps, 1 - eps)
                return -(labels * np.log(pr) + (1 - labels) * np.log(1 - pr)).mean()

            best2 = None
            for a0, b0 in [(1.0, 0.0), (0.5, 0.0), (2.0, 0.0),
                           (1.0, -1.0), (1.0, 1.0), (0.3, 0.0)]:
                r = optimize.minimize(linear_obj, x0=[a0, b0], method="L-BFGS-B",
                                      bounds=[(0.01, 50.0), (-10.0, 10.0)])
                if best2 is None or r.fun < best2.fun:
                    best2 = r
            bic2 = best2.fun * n + 2 * log_n

            # --- Select best model ---
            bics = [bic0, bic1, bic2]
            choice = int(np.argmin(bics))
            if choice == 0:
                self.model_type_ = 'identity'
            elif choice == 1:
                self.model_type_ = 'temperature'
                self.params_ = {'T': float(best1.x[0])}
            else:
                self.model_type_ = 'linear'
                self.params_ = {'a': float(best2.x[0]), 'b': float(best2.x[1])}

        else:
            self.is_binary = False
            logits = np.log(np.clip(probs, eps, 1.0))
            C = logits.shape[1]

            # --- Model 0: Identity ---
            nll0 = self._nll_from_logits(logits, labels)
            bic0 = nll0 * n

            # --- Model 1: Single temperature (1 param) ---
            def temp_obj(T_arr):
                T = max(T_arr[0], 0.01)
                return self._nll_from_logits(logits / T, labels)

            best1 = None
            for t0 in [0.3, 0.5, 1.0, 1.5, 2.0, 3.0, 5.0, 8.0]:
                r = optimize.minimize(temp_obj, x0=[t0],
                                      bounds=[(0.01, 50.0)], method="L-BFGS-B")
                if best1 is None or r.fun < best1.fun:
                    best1 = r
            bic1 = best1.fun * n + 1 * log_n
            T_glob = float(best1.x[0])

            # --- Model 2: Per-class temperature (C params) ---
            def pct_obj(params):
                T = np.maximum(params, 0.01)
                return self._nll_from_logits(logits / T[np.newaxis, :], labels)

            best2 = None
            for f0 in [0.7, 1.0, 1.3]:
                x0 = np.full(C, T_glob * f0)
                r = optimize.minimize(pct_obj, x0=x0, method="L-BFGS-B",
                                      bounds=[(0.01, 50.0)] * C)
                if best2 is None or r.fun < best2.fun:
                    best2 = r
            bic2 = best2.fun * n + C * log_n

            # --- Model 3: Per-class temp + bias (2C params) ---
            reg = C * 0.5 / max(n, 1)

            def pctb_obj(params):
                T = np.maximum(params[:C], 0.01)
                b = params[C:]
                s = logits / T[np.newaxis, :] + b[np.newaxis, :]
                raw = self._nll_from_logits(s, labels)
                return raw + reg * (np.sum((T - T_glob) ** 2) + np.sum(b ** 2))

            best3 = None
            for f0 in [0.7, 1.0, 1.5]:
                x0 = np.zeros(2 * C)
                x0[:C] = T_glob * f0
                r = optimize.minimize(pctb_obj, x0=x0, method="L-BFGS-B",
                                      bounds=[(0.01, 50.0)] * C + [(-5.0, 5.0)] * C)
                if best3 is None or r.fun < best3.fun:
                    best3 = r

            # Raw NLL for model 3 (without regularization penalty)
            if best3 is not None:
                T3 = np.maximum(best3.x[:C], 0.01)
                b3 = best3.x[C:]
                s3 = logits / T3[np.newaxis, :] + b3[np.newaxis, :]
                raw_nll3 = self._nll_from_logits(s3, labels)
                bic3 = raw_nll3 * n + 2 * C * log_n
            else:
                bic3 = np.inf

            # --- Select best model ---
            bics = [bic0, bic1, bic2, bic3]
            choice = int(np.argmin(bics))
            if choice == 0:
                self.model_type_ = 'identity'
            elif choice == 1:
                self.model_type_ = 'temperature'
                self.params_ = {'T': T_glob}
            elif choice == 2:
                self.model_type_ = 'per_class_temp'
                self.params_ = {'T': best2.x.copy()}
            else:
                self.model_type_ = 'per_class_temp_bias'
                self.params_ = {'T': best3.x[:C].copy(), 'b': best3.x[C:].copy()}

        return self

    def predict_proba(self, probs):
        eps = 1e-15

        if self.model_type_ == 'identity':
            if self.is_binary:
                return np.clip(probs, 0, 1)
            else:
                p = np.clip(probs, eps, 1.0)
                return p / p.sum(axis=1, keepdims=True)

        if self.is_binary:
            p = np.clip(probs, eps, 1 - eps)
            if self.model_type_ == 'temperature':
                T = max(self.params_['T'], 0.01)
                log2d = np.column_stack([np.log(1 - p), np.log(p)])
                s = log2d / T
                s = s - s.max(axis=1, keepdims=True)
                e = np.exp(s)
                return (e / e.sum(axis=1, keepdims=True))[:, 1]
            elif self.model_type_ == 'linear':
                a = max(self.params_['a'], 0.01)
                b = self.params_['b']
                lp = np.clip(a * np.log(p / (1 - p)) + b, -30, 30)
                return 1.0 / (1.0 + np.exp(-lp))
        else:
            logits = np.log(np.clip(probs, eps, 1.0))
            if self.model_type_ == 'temperature':
                s = logits / max(self.params_['T'], 0.01)
            elif self.model_type_ == 'per_class_temp':
                T = np.maximum(self.params_['T'], 0.01)
                s = logits / T[np.newaxis, :]
            elif self.model_type_ == 'per_class_temp_bias':
                T = np.maximum(self.params_['T'], 0.01)
                s = logits / T[np.newaxis, :] + self.params_['b'][np.newaxis, :]
            s = s - s.max(axis=1, keepdims=True)
            e = np.exp(s)
            return e / e.sum(axis=1, keepdims=True)
